a<-commandArgs(TRUE);p<-a[1];s<-read.csv(file.path(p,'sources_viability.csv'));r<-read.csv(file.path(p,'runs_viability.csv'));b<-read.csv(file.path(p,'blocks.csv'))
cat('sources',nrow(s),'min>=20',sum(s$min_population>=20),'endpoint viable',sum(s$viability=='viable'),'cap ticks',sum(s$source_cap_ticks),'min range',range(s$min_population),'max peak',max(s$source_max),'\n')
cat('assays',nrow(r),'min>=20',sum(r$min_population>=20),'endpoint viable',sum(r$viability=='viable'),'weak',sum(r$viability=='weak'),'crashed',sum(r$viability=='crashed'),'extinct',sum(r$final_agents==0),'cap ticks',sum(r$cap_ticks),'min range',range(r$min_population),'max peak',max(r$max_population),'\n')
out<-do.call(rbind,lapply(split(r,paste(r$density,r$threshold,r$food_rate,r$age_mode)),function(x)data.frame(density=x$density[1],threshold=x$threshold[1],food_rate=x$food_rate[1],age_mode=x$age_mode[1],n=nrow(x),stable=sum(x$stable),viable=sum(x$viability=='viable'),extinct=sum(x$final_agents==0),cap_ticks=sum(x$cap_ticks),min= min(x$min_population),max_peak=max(x$max_population))));write.csv(out,file.path(p,'stability-summary.csv'),row.names=FALSE);print(out,row.names=FALSE)
